-- Forty additional, non-duplicate longevity topics spanning human biomarkers,
-- emerging mechanisms, organ ageing, functional outcomes, and translational
-- geroscience. Every broad term requires explicit ageing or longevity context.

on conflict (slug) do update set
  name = excluded.name,
  description = excluded.description,
  literature_query = excluded.literature_query,
  trials_query = excluded.trials_query,
  sort_order = excluded.sort_order,
  enabled = true,
  updated_at = now();

select public.refresh_intelligence_entities();

do $$
declare enabled_count integer;
begin
  select count(*) into enabled_count from public.intelligence_topics where enabled;
  if enabled_count < 82 then
    raise exception 'Expected at least 82 enabled longevity topics, found %', enabled_count;
  end if;
end $$;
